CREATE TABLE `booking` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bookingRef` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `guestId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `promoCodeId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currency` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AED',
  `status` enum('PENDING','CONFIRMED','CANCELLED','CHECKED_IN','CHECKED_OUT','NO_SHOW') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `totalAmount` double NOT NULL,
  `specialRequests` text COLLATE utf8mb4_unicode_ci,
  `checkIn` date NOT NULL,
  `checkOut` date NOT NULL,
  `adults` int NOT NULL DEFAULT '1',
  `children` int NOT NULL DEFAULT '0',
  `roomsCount` int NOT NULL DEFAULT '1',
  `guestPrefix` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `firstName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `lastName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `country` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zipCode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `newsletter` tinyint(1) NOT NULL DEFAULT '0',
  `confirmedAt` datetime(3) DEFAULT NULL,
  `cancelledAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `lodgifyBookingId` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lodgifySource` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Booking_bookingRef_key` (`bookingRef`),
  UNIQUE KEY `Booking_lodgifyBookingId_key` (`lodgifyBookingId`),
  KEY `Booking_guestId_fkey` (`guestId`),
  KEY `Booking_promoCodeId_fkey` (`promoCodeId`),
  CONSTRAINT `Booking_guestId_fkey` FOREIGN KEY (`guestId`) REFERENCES `guest` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Booking_promoCodeId_fkey` FOREIGN KEY (`promoCodeId`) REFERENCES `promocode` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
