DROP TABLE IF EXISTS `bookingitem`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookingitem` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bookingId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `roomTypeId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ratePlanId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nightlyRate` double NOT NULL,
  `nights` int NOT NULL,
  `subtotal` double NOT NULL,
  `serviceCharge` double NOT NULL,
  `municipalityFee` double NOT NULL,
  `vat` double NOT NULL,
  `total` double NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `BookingItem_bookingId_fkey` (`bookingId`),
  KEY `BookingItem_roomTypeId_fkey` (`roomTypeId`),
  KEY `BookingItem_ratePlanId_fkey` (`ratePlanId`),
  CONSTRAINT `BookingItem_bookingId_fkey` FOREIGN KEY (`bookingId`) REFERENCES `booking` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `BookingItem_ratePlanId_fkey` FOREIGN KEY (`ratePlanId`) REFERENCES `rateplan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `BookingItem_roomTypeId_fkey` FOREIGN KEY (`roomTypeId`) REFERENCES `roomtype` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

