INSERT INTO `roomtype` VALUES ('cmsisqcpm000apjyh2purt74f','cmsisqcp60008pjyhe51m8vt3','Ocean King','ocean-king','KING',2,45,'OCEAN','Wake to sweeping Arabian Gulf views from a serene king bedroom with warm coastal interiors and a private balcony.','/rooms/room-1.jpg',1,0,'2026-08-07 10:22:45.465','2026-08-07 10:51:59.172',598128,664916),('cmsisqcqj000ypjyh98o1parv','cmsisqcp60008pjyhe51m8vt3','Palm King','palm-king','KING',2,42,'PALM','Overlook the iconic palm fronds from a refined king suite of calm neutrals and soft natural light.','/rooms/room-5.jpg',1,0,'2026-08-07 10:22:45.500','2026-08-07 10:51:59.208',714507,781617),('cmsisqcrk001lpjyhejx6d2b2','cmsisqcr7001jpjyhl15200z1','Garden Queen','garden-queen','QUEEN',2,38,'GARDEN','A tranquil queen room framed by landscaped gardens — ideal for couples seeking quiet luxury.','/rooms/room-3.jpg',1,0,'2026-08-07 10:22:45.536','2026-08-07 10:22:45.536',NULL,NULL),('cmsisqcsc0027pjyh0s1cioiq','cmsisqcr7001jpjyhl15200z1','Pool Queen','pool-queen','QUEEN',2,40,'POOL','Watch the lagoon shimmer from your balcony in this light-filled queen room with poolside energy.','/rooms/room-1.jpg',1,0,'2026-08-07 10:22:45.564','2026-08-07 10:22:45.564',NULL,NULL),('cmsisqct7002spjyhgcj12a2h','cmsisqcsu002qpjyhjqe51jdl','Club Ocean King','club-ocean-king','KING',2,48,'OCEAN','Elevated club privileges meet panoramic ocean vistas — breakfast, canapes, and priority access included.','/rooms/room-3.jpg',1,0,'2026-08-07 10:22:45.595','2026-08-07 10:22:45.595',NULL,NULL),('cmsisqcu4003jpjyhso897omz','cmsisqcts003hpjyh37053gbw','Club Garden Queen','club-garden-queen','QUEEN',2,44,'GARDEN','Club-level comfort with serene garden outlooks and exclusive lounge hospitality throughout your stay.','/rooms/room-1.jpg',1,0,'2026-08-07 10:22:45.628','2026-08-07 10:22:45.628',NULL,NULL),('cmsisqcvn0048pjyh4wj7006m','cmsisqcup0046pjyh1rlvvsxm','Executive Suite','executive-suite','KING',3,85,'OCEAN','Separate living lounge and bedroom with floor-to-ceiling ocean glass — crafted for unhurried stays.','/rooms/room-3.jpg',1,0,'2026-08-07 10:22:45.683','2026-08-07 10:22:45.683',NULL,NULL),('cmsisqcwe0053pjyhr8pl40f5','cmsisqcup0046pjyh1rlvvsxm','Royal Suite','royal-suite','KING',4,120,'PALM','Expansive suite living with dual balconies and bespoke furnishings overlooking the palm crown.','/rooms/room-1.jpg',1,0,'2026-08-07 10:22:45.710','2026-08-07 10:22:45.710',NULL,NULL),('cmsisqcx9005xpjyhxzx6uida','cmsisqcx0005vpjyhxof2i3oy','Family Connecting','family-connecting','KING',5,72,'GARDEN','Connecting king and twin rooms designed for families — space to gather and rest in equal measure.','/rooms/room-3.jpg',1,0,'2026-08-07 10:22:45.742','2026-08-07 10:22:45.742',NULL,NULL),('cmsisqcy1006ppjyhqyaopo6h','cmsisqcxr006npjyhuejyh5ze','The Serrano Presidential','presidential-suite','KING',6,280,'OCEAN','The pinnacle of Serrano hospitality — private terrace, dedicated butler, and uninterrupted Gulf horizons.','/rooms/room-1.jpg',1,0,'2026-08-07 10:22:45.769','2026-08-07 10:22:45.769',NULL,NULL);
